-- R-06-E1 and R-10: fresh service-role call, false-hash poisoning and replay.
-- A separate test file/psql connection is required: do not concatenate with test 13.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;
select no_plan();
create function pg_temp.hac12_payload() returns jsonb language sql as $$
  select '{
    "schemaVersion":"2.0",
    "origin":{"facilityId":"c2330000-0000-4000-8000-000000000001","label":"browser assertion ignored"},
    "destination":{"facilityId":"c2330000-0000-4000-8000-000000000002"},
    "pickupWindow":{"startsAt":"2026-10-01T10:00:00Z","endsAt":"2026-10-01T12:00:00Z"},
    "deliveryWindow":{"startsAt":"2026-10-02T10:00:00Z","endsAt":"2026-10-02T12:00:00Z"},
    "acceptedModes":["ROAD"],
    "requiredEquipment":null,
    "cargoSpecification":{
      "categoryCode":"GENERAL","description":"Synthetic test cargo",
      "packaging":"PALLET","totalWeightKg":1000,"totalVolumeM3":2,
      "divisible":true,"requirements":[],
      "units":[{"packageType":"PALLET","quantity":1,"weightPerUnitKg":1000,
        "volumePerUnitM3":2,"dimensionsCm":{"length":100,"width":100,"height":200},
        "indivisible":false,"stackable":true}]
    },
    "contacts":{
      "pickup":{"name":"QA Pickup","phoneE164":"+51911111111"},
      "recipient":{"name":"QA Recipient","phoneE164":"+51922222222"}
    },
    "budget":{"amount":500,"currency":"USD"}
  }'::jsonb;
$$;


-- First canonical RPC invocation in this connection is service_role, not authenticated.
set local role service_role;
set local "request.jwt.claims" to '{"role":"service_role"}';
select lives_ok($$ select public.create_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','a1400000-0000-4000-8000-000000000001',private.hash_v2_freight_payload(pg_temp.hac12_payload()),pg_temp.hac12_payload()) $$,'R-10 fresh service_role connection can call the canonical RPC');
select is((select count(*)::integer from public.freight_requests where creation_idempotency_key='a1400000-0000-4000-8000-000000000001'),1,'fresh service role persists one canonical row');
reset role;
create function pg_temp.insert_receipt_copy(p_hash text) returns void language sql as $$
  insert into public.freight_requests
  select (jsonb_populate_record(null::public.freight_requests,
    to_jsonb(r) || jsonb_build_object('id','a1400000-0000-4000-8000-000000000002','code','V2-R06-E1-COPY',
      'creation_idempotency_key','a1400000-0000-4000-8000-000000000002','creation_payload_hash',p_hash))).*
  from public.freight_requests r where creation_idempotency_key='a1400000-0000-4000-8000-000000000001';
$$;
set local role authenticated;
set local "request.jwt.claims" to '{"sub":"c2310000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$ select pg_temp.insert_receipt_copy(repeat('0',64)) $$,'PT400','VALIDATION_ERROR','R-06-E1 rejects a well-formed false receipt hash');
select is((select count(*)::integer from public.freight_requests where creation_idempotency_key='a1400000-0000-4000-8000-000000000002'),0,'false hash consumes no row or idempotency key');
select lives_ok($$ select public.create_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','a1400000-0000-4000-8000-000000000002',private.hash_v2_freight_payload(pg_temp.hac12_payload()),pg_temp.hac12_payload()) $$,'legitimate RPC can use the rejected insert key');
select lives_ok($$ select public.create_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','a1400000-0000-4000-8000-000000000002',private.hash_v2_freight_payload(pg_temp.hac12_payload()),pg_temp.hac12_payload()) $$,'same canonical payload and key replay successfully');
select is((select count(*)::integer from public.freight_requests where creation_idempotency_key='a1400000-0000-4000-8000-000000000002'),1,'legitimate retry persists only once');
reset role;
delete from public.freight_requests where creation_idempotency_key='a1400000-0000-4000-8000-000000000002';
set local role authenticated;
select lives_ok($$ select pg_temp.insert_receipt_copy(private.hash_v2_freight_payload(pg_temp.hac12_payload())) $$,'coherent positive direct INSERT still passes tenant RLS');
select lives_ok($$ select public.create_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','a1400000-0000-4000-8000-000000000002',private.hash_v2_freight_payload(pg_temp.hac12_payload()),pg_temp.hac12_payload()) $$,'positive direct INSERT can be replayed through the canonical RPC');
select ok(not has_schema_privilege('anon','private','USAGE'),'R-10 does not expose private schema to anon');
select is(private.canonical_v2_payload('{"b":1.0,"a":[0.000001,1e-7,1e21,-0.0]}'::jsonb),
  '{"a":[0.000001,1e-7,1e+21,0],"b":1}','canonical number boundaries and object ordering match Node');
